{"command": "python3 << 'EOF'
import fitz
doc = fitz.open('/root/input/input.pdf')
page = doc[0]

# Find reason for appeal lines (underscore lines) to know coordinates
# Also find the Date label position (right side under signature line)
# Look for underscore lines
blocks = page.get_text("dict")
# Find all lines with underscores to know line coordinates
lines_info = []
for block in blocks["blocks"]:
    if "lines" not in block:
        continue
    for line in block["lines"]:
        for span in line["spans"]:
            text = span["text"].strip()
            if text.startswith("___") or text == "Date":
                lines_info.append((span["text"][:40], span["bbox"]))
for t, b in lines_info[:20]:
    print(t, b)
EOF", "summary": "Find underscore lines and Date position"}

